def decode_png():
    """Decode the embedded render; verify size + sha256 before use."""
    data = base64.b64decode(PNG_B64)
    if len(data) != EXPECTED_BYTES:
        raise SystemExit(
            "embedded PNG size mismatch: %d != %d" % (len(data), EXPECTED_BYTES)
        )
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        raise SystemExit("embedded PNG sha256 mismatch")
    return data


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "output")
    os.makedirs(out_dir, exist_ok=True)
    data = decode_png()
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as f:
        f.write(data)
    print("wrote %s (%d bytes, sha256 %s)" % (path, len(data), EXPECTED_SHA256))
    return 0


if __name__ == "__main__":
    sys.exit(main())
